bool LucisParser::sempred(RuleContext *context, size_t ruleIndex, size_t predicateIndex) {
  switch (ruleIndex) {
    case 90: return expressionSempred(antlrcpp::downCast<ExpressionContext *>(context), predicateIndex);
    case 91: return typeSpecSempred(antlrcpp::downCast<TypeSpecContext *>(context), predicateIndex);

  default:
    break;
  }
  return true;
}

